package com.securelib.ratelimit

import java.security.SecureRandom
import javax.crypto.Cipher
import javax.crypto.spec.{GCMParameterSpec, SecretKeySpec}
import java.util.Base64
import java.util.concurrent.ConcurrentHashMap
import java.util.concurrent.atomic.AtomicLong
import java.nio.ByteBuffer
import java.time.Instant

/**
 * Encrypted rate limit store using AES-GCM.
 * Each client's request count is stored encrypted with a per-client nonce.
 * The window timestamp is bound to the ciphertext via GCM AAD to ensure freshness.
 */
object RateLimitConfig {
  val MAX_REQUESTS_PER_WINDOW: Int = 100
  val WINDOW_SIZE_SECONDS: Long = 60
  val GCM_TAG_LENGTH: Int = 128
  val NONCE_LENGTH: Int = 12
}

case class EncryptedCounter(
  ciphertext: Array[Byte],
  nonce: Array[Byte],
  windowStart: Long
)

class CryptoRateLimiter(masterKey: Array[Byte]) {
  require(masterKey.length == 32, "Master key must be 256 bits")

  private val store = new ConcurrentHashMap[String, EncryptedCounter]()
  private val random = new SecureRandom()
  private val keySpec = new SecretKeySpec(masterKey, "AES")

  /**
   * Derives a per-client key from the master key and client ID.
   * Uses HKDF-like construction for domain separation.
   */
  private def deriveClientKey(clientId: String): SecretKeySpec = {
    val hmac = javax.crypto.Mac.getInstance("HmacSHA256")
    hmac.init(keySpec)
    hmac.update("rate-limit-v1|".getBytes("UTF-8"))
    hmac.update(clientId.getBytes("UTF-8"))
    val derived = hmac.doFinal()
    new SecretKeySpec(derived, 0, 32, "AES")
  }

  /**
   * Generates a fully random 12-byte nonce. The window timestamp is bound to
   * the ciphertext via GCM AAD rather than being embedded in the nonce, so
   * the nonce retains full 96-bit entropy and reuse risk is minimized.
   */
  private def generateNonce(): Array[Byte] = {
    val nonce = new Array[Byte](RateLimitConfig.NONCE_LENGTH)
    random.nextBytes(nonce)
    nonce
  }

  /**
   * Encodes the window timestamp for use as GCM additional authenticated data.
   */
  private def windowAad(windowStart: Long): Array[Byte] = {
    val prefix = "rate-limit-window|".getBytes("UTF-8")
    val ws = ByteBuffer.allocate(8).putLong(windowStart).array()
    val aad = new Array[Byte](prefix.length + ws.length)
    System.arraycopy(prefix, 0, aad, 0, prefix.length)
    System.arraycopy(ws, 0, aad, prefix.length, ws.length)
    aad
  }

  private def encryptCounter(count: Long, clientKey: SecretKeySpec, nonce: Array[Byte], windowStart: Long): Array[Byte] = {
    val cipher = Cipher.getInstance("AES/GCM/NoPadding")
    val gcmSpec = new GCMParameterSpec(RateLimitConfig.GCM_TAG_LENGTH, nonce)
    cipher.init(Cipher.ENCRYPT_MODE, clientKey, gcmSpec)
    cipher.updateAAD(windowAad(windowStart))
    val plaintext = ByteBuffer.allocate(8).putLong(count).array()
    cipher.doFinal(plaintext)
  }

  private def decryptCounter(ciphertext: Array[Byte], clientKey: SecretKeySpec, nonce: Array[Byte], windowStart: Long): Long = {
    val cipher = Cipher.getInstance("AES/GCM/NoPadding")
    val gcmSpec = new GCMParameterSpec(RateLimitConfig.GCM_TAG_LENGTH, nonce)
    cipher.init(Cipher.DECRYPT_MODE, clientKey, gcmSpec)
    cipher.updateAAD(windowAad(windowStart))
    val plaintext = cipher.doFinal(ciphertext)
    ByteBuffer.wrap(plaintext).getLong
  }

  /**
   * Computes the current window start timestamp.
   */
  private def currentWindowStart(): Long = {
    val now = Instant.now().getEpochSecond
    now - (now % RateLimitConfig.WINDOW_SIZE_SECONDS)
  }

  /**
   * Checks if a request should be allowed and increments the counter.
   * Returns true if the request is within rate limits.
   *
   * Thread-safety: uses ConcurrentHashMap.compute for atomic updates.
   */
  def allowRequest(clientId: String): Boolean = {
    val clientKey = deriveClientKey(clientId)
    val windowStart = currentWindowStart()
    var allowed = false

    store.compute(clientId, (_, existing) => {
      val currentCount: Long = if (existing == null || existing.windowStart != windowStart) {
        0L
      } else {
        try {
          decryptCounter(existing.ciphertext, clientKey, existing.nonce, existing.windowStart)
        } catch {
          case _: Exception => 0L
        }
      }

      // Rate limit check: compare as Long directly
      if (currentCount < RateLimitConfig.MAX_REQUESTS_PER_WINDOW.toLong) {
        allowed = true
        val newCount = currentCount + 1
        val nonce = generateNonce()
        val ciphertext = encryptCounter(newCount, clientKey, nonce, windowStart)
        EncryptedCounter(ciphertext, nonce, windowStart)
      } else {
        allowed = false
        existing
      }
    })

    allowed
  }

  /**
   * Returns the current request count for a client (for monitoring).
   */
  def getCount(clientId: String): Long = {
    val entry = store.get(clientId)
    if (entry == null) return 0L
    val windowStart = currentWindowStart()
    if (entry.windowStart != windowStart) return 0L
    val clientKey = deriveClientKey(clientId)
    try {
      decryptCounter(entry.ciphertext, clientKey, entry.nonce, entry.windowStart)
    } catch {
      case _: Exception => 0L
    }
  }

  /**
   * Resets rate limit for a specific client (admin operation).
   */
  def resetClient(clientId: String): Unit = {
    store.remove(clientId)
  }
}

/**
 * Service layer that uses the rate limiter.
 */
class SecureApiService(limiter: CryptoRateLimiter) {
  def handleRequest(clientId: String, payload: String): Either[String, String] = {
    if (clientId == null || clientId.isEmpty) {
      Left("Invalid client ID")
    } else if (!limiter.allowRequest(clientId)) {
      Left("Rate limit exceeded")
    } else {
      Right(s"Processed: ${payload.take(100)}")
    }
  }
}
